// Decide which page to show: the form (no post yet) or the analysis.
const q = $input.item.json.query || {};
return { json: { ...$input.item.json, hasPost: String(q.post || '').trim().length > 0 } };

const ALLOWED = {"wishlist_reasons": ["price_watch", "bookmark_inspiration", "occasion_planning", "compare_later", "gift_or_ask_others", "size_unavailable", "other"], "blockers": ["fit_size_uncertainty", "price_too_high_or_waiting_for_sale", "discount_unpredictability", "reviews_photos_insufficient", "quality_fabric_doubt", "returns_refund_fear", "delivery_time_or_cost", "out_of_stock_or_size_missing", "styling_confusion", "occasion_timing_not_urgent", "compare_with_other_platform", "needs_social_validation", "cart_checkout_friction", "trust_authenticity_concern", "wishlist_ux_problem", "no_blocker_purchased", "none_mentioned"], "uncertainties": ["fit", "size", "fabric_quality", "colour_accuracy", "price_fairness", "styling", "occasion_suitability", "return_policy", "delivery_date", "authenticity", "review_credibility", "none"], "outside_sources": ["instagram", "youtube", "reddit", "google_search", "other_shopping_app", "friends_family", "brand_website", "offline_store_trial", "price_tracker", "whatsapp_group", "none"], "intent": ["genuine_purchase_intent", "bookmarking_only", "price_watching", "unclear"], "segment": ["value_seeker", "trend_follower", "occasion_shopper", "size_challenged", "plus_size", "first_time_online_buyer", "male_shopper", "beauty_shopper", "gen_z", "working_professional", "unknown"], "platform": ["myntra", "ajio", "nykaa_fashion", "meesho", "amazon", "flipkart", "other", "unknown"], "postpone": ["waiting_for_sale_or_price_drop", "waiting_for_payday_or_budget", "no_occasion_yet", "checking_other_platforms", "asking_friends_or_family", "waiting_for_restock_or_size", "unresolved_fit_or_quality_doubt", "forgot_or_distracted", "comparing_shortlisted_items", "none"]};

const post = $('Build Gemini request').item.json.post;
const resp = $input.item.json;
const base = { id: post.id, source: post.source, platform: post.platform, date: post.date, text: post.text };
let t = null, err = '';
try {
  const raw = resp.candidates[0].content.parts.map(p => p.text || '').join('');
  const m = raw.match(/\{[\s\S]*\}/);
  t = JSON.parse(m ? m[0] : raw);
} catch (e) {
  err = JSON.stringify(resp.error || resp).slice(0, 300);
}
if (!t) return { json: { ...base, relevant: '', error: err || 'unparseable output' } };

const keep = (arr, allowed) => (Array.isArray(arr) ? arr : []).filter(x => allowed.includes(x));
const norm = s => String(s).toLowerCase().replace(/\s+/g, ' ');
const BADL = ['unknown', 'unclear', 'none', 'none_mentioned', 'no_blocker_purchased', 'n/a', 'null', ''];
const evidence = (Array.isArray(t.evidence) ? t.evidence : [])
  .filter(e => e && e.quote && !BADL.includes(String(e.label || '').toLowerCase()) && norm(post.text).includes(norm(e.quote)));
let sev = parseInt(t.severity, 10); if (!(sev >= 1 && sev <= 3)) sev = 1;
const j = a => a.join('|');
const BAD = ['unknown', 'unclear', 'none', 'none_mentioned', 'no_blocker_purchased', 'n/a', 'null', ''];
const clean = v => BAD.includes(String(v == null ? '' : v).trim().toLowerCase()) ? '' : String(v).trim();
const platform = post.platform && post.platform !== 'unknown' ? post.platform
  : (ALLOWED.platform.includes(t.platform) ? clean(t.platform) : '');
const blk = keep(t.blockers, ALLOWED.blockers).filter(x => clean(x));
const unc = keep(t.uncertainties, ALLOWED.uncertainties).filter(x => clean(x));
const wr = keep(t.wishlist_reasons, ALLOWED.wishlist_reasons).filter(x => clean(x));
const pp = keep(t.postponement_trigger, ALLOWED.postpone).filter(x => clean(x));
const os = keep(t.outside_sources, ALLOWED.outside_sources).filter(x => clean(x));
const need = clean(t.unmet_need), cmp = clean(t.comparison_behavior);
const said = t.relevant === true || ['true', 'yes'].includes(String(t.relevant).toLowerCase());
// a row only counts as relevant when it carries at least one real finding (praise-only posts stay blank)
const isRel = said && (blk.length || unc.length || wr.length || pp.length || os.length || need || cmp);
const row = { ...base, platform,
  relevant: isRel ? 'yes' : '',
  intent: isRel && ALLOWED.intent.includes(t.intent) ? clean(t.intent) : '',
  wishlist_reasons: isRel ? j(wr) : '',
  blockers: j(blk),
  uncertainties: j(keep(t.uncertainties, ALLOWED.uncertainties).filter(x => clean(x))),
  outside_sources: j(keep(t.outside_sources, ALLOWED.outside_sources).filter(x => clean(x))),
  postponement_trigger: j(keep(t.postponement_trigger, ALLOWED.postpone).filter(x => clean(x))),
  comparison_behavior: String(t.comparison_behavior || '').slice(0, 300),
  segment: ALLOWED.segment.includes(t.segment) ? clean(t.segment) : '',
  unmet_need: isRel ? clean(t.unmet_need) : '', severity: isRel ? sev : '',
  evidence: evidence.length ? JSON.stringify(evidence) : '', error: '' };
if (!isRel) for (const k of ['intent','wishlist_reasons','blockers','uncertainties','outside_sources','postponement_trigger','comparison_behavior','segment','unmet_need','severity','evidence']) row[k] = '';
return { json: row };

// Turn the parsed tags into a readable result page.
const STYLE = "<style>body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;max-width:760px;margin:0 auto;padding:24px 16px;color:#1d2433;background:#fafafa;line-height:1.5}h1{font-size:1.5rem;margin:0 0 4px}p.s{color:#5b6475;margin:0 0 18px}textarea{width:100%;min-height:130px;font:inherit;padding:10px;border:1px solid #c9ced8;border-radius:8px;box-sizing:border-box}select,button{font:inherit;padding:8px 12px;border-radius:8px;border:1px solid #c9ced8;background:#fff}button.go{background:#1f4e99;color:#fff;border-color:#1f4e99;font-weight:700}.ex{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0 16px}.ex button{font-size:.85rem}table{border-collapse:collapse;width:100%;background:#fff;margin:12px 0}td,th{border:1px solid #dde1e8;padding:8px 10px;text-align:left;vertical-align:top;font-size:.95rem}th{background:#eef1f6;width:36%}.q{font-style:italic}.n{color:#5b6475;font-size:.85rem}a{color:#1f4e99}</style>";
const r = $input.item.json;
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nice = s => esc(String(s || '').split('|').filter(Boolean).map(x => x.replace(/_/g, ' ')).join(', ')) || '<span class="n">not mentioned</span>';
let ev = [];
try { ev = r.evidence ? JSON.parse(r.evidence) : []; } catch (e) { ev = []; }
const rows = [
  ['Relevant to buying?', r.relevant === 'yes' ? 'Yes' : 'No buying factor found'],
  ['Why it was saved (wishlist reasons)', nice(r.wishlist_reasons)],
  ['What blocks the purchase', nice(r.blockers)],
  ['What the buyer is unsure about', nice(r.uncertainties)],
  ['Why the purchase is delayed', nice(r.postponement_trigger)],
  ['Where they look outside the app', nice(r.outside_sources)],
  ['How they compare options', esc(r.comparison_behavior) || '<span class="n">not mentioned</span>'],
  ['Intent', nice(r.intent)],
  ['Segment signal', nice(r.segment)],
  ['Unmet need', esc(r.unmet_need) || '<span class="n">none stated</span>'],
  ['Severity (1 minor - 3 stops the purchase)', esc(r.severity) || '<span class="n">-</span>'],
];
const evid = ev.length ? ev.map(e => `<tr><th>${esc(String(e.label).replace(/_/g, ' '))}</th><td class="q">"${esc(e.quote)}"</td></tr>`).join('') : '<tr><td colspan="2" class="n">No quote-backed findings.</td></tr>';
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Discovery engine - result</title>${STYLE}</head><body>
<h1>What the engine found</h1>
<p class="s">Post: <span class="q">"${esc(r.text)}"</span></p>
${r.error ? `<p>The model could not tag this post right now (${esc(r.error).slice(0, 160)}). The free tier is rate-limited; wait a minute and try again.</p>` : ''}
<table>${rows.map(([k, v]) => `<tr><th>${k}</th><td>${v}</td></tr>`).join('')}</table>
<h2 style="font-size:1.1rem">Evidence (verbatim quotes, checked against the post)</h2>
<table>${evid}</table>
<p><a href="?">Analyse another post</a></p>
</body></html>`;
return { json: { html } };

// No ?post= yet: show the page where an evaluator pastes a review, comment or survey answer.
const STYLE = "<style>body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;max-width:760px;margin:0 auto;padding:24px 16px;color:#1d2433;background:#fafafa;line-height:1.5}h1{font-size:1.5rem;margin:0 0 4px}p.s{color:#5b6475;margin:0 0 18px}textarea{width:100%;min-height:130px;font:inherit;padding:10px;border:1px solid #c9ced8;border-radius:8px;box-sizing:border-box}select,button{font:inherit;padding:8px 12px;border-radius:8px;border:1px solid #c9ced8;background:#fff}button.go{background:#1f4e99;color:#fff;border-color:#1f4e99;font-weight:700}.ex{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0 16px}.ex button{font-size:.85rem}table{border-collapse:collapse;width:100%;background:#fff;margin:12px 0}td,th{border:1px solid #dde1e8;padding:8px 10px;text-align:left;vertical-align:top;font-size:.95rem}th{background:#eef1f6;width:36%}.q{font-style:italic}.n{color:#5b6475;font-size:.85rem}a{color:#1f4e99}</style>";
const examples = [
  "My order is delivered but the size is an issue and I cannot exchange it because the delivery still shows out for delivery.",
  "Bhai maine jitne bhi sweatshirt jacket wishlist me rakha tha sab ke price badh gaye",
  "I swear 1st dress maine cart me daal ke rakha hua hai for function joki mujhe dar lgrha tha kaisa aayega",
  "Good products. App has good collection but bit pricy compared to other apps like flipkart, amazon. Also the discounts and offers are very volatile"
];
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wishlist discovery engine - try it</title>${STYLE}</head><body>
<h1>Wishlist discovery engine</h1>
<p class="s">Paste one public post about shopping on a fashion app (an app review, YouTube comment, Reddit post or survey answer). The engine tags it the same way it tagged 250 public Myntra posts: why people wishlist, what blocks the purchase, what they are unsure about, where they look outside the app, and the unmet need, each backed by a quote from the post. Hinglish works.</p>
<form method="get">
<textarea name="post" required maxlength="2000" placeholder="Paste a review or comment here"></textarea>
<div class="ex">Try an example from the real data: ${examples.map((e, i) => `<button type="button" onclick="document.querySelector('textarea').value=this.dataset.t" data-t="${esc(e)}">Example ${i + 1}</button>`).join('')}</div>
<label>Source <select name="source"><option value="app_store">App review</option><option value="youtube_comment">YouTube comment</option><option value="reddit">Reddit</option><option value="survey">Survey answer</option></select></label>
<p><button class="go" type="submit">Analyse</button></p>
</form>
<p class="n">Model: Google Gemini (free tier), fixed label taxonomy, quotes checked against the post. Part of a student product case study; not affiliated with Myntra.</p>
</body></html>`;
return [{ json: { html } }];
